using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;

namespace MobileBackend.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class MediaUploadController : ControllerBase
    {
        private readonly IMemoryCache _cache;
        private readonly IMediaProcessor _processor;
        private static readonly ConcurrentDictionary<string, SemaphoreSlim> _locks = new();

        public MediaUploadController(IMemoryCache cache, IMediaProcessor processor)
        {
            _cache = cache;
            _processor = processor;
        }

        [HttpPost("upload")]
        public async Task<IActionResult> Upload(IFormFile file, [FromHeader(Name = "X-Device-Id")] string deviceId)
        {
            if (file == null || file.Length == 0 || file.Length > 10_000_000)
                return BadRequest("Invalid file");

            if (string.IsNullOrWhiteSpace(deviceId) || deviceId.Length > 64)
                return BadRequest("Invalid device ID");

            var sanitizedDeviceId = SanitizeDeviceId(deviceId);
            var contentHash = await ComputeContentHashAsync(file);
            var cacheKey = BuildCacheKey(sanitizedDeviceId, contentHash);

            var semaphore = _locks.GetOrAdd(cacheKey, _ => new SemaphoreSlim(1, 1));
            await semaphore.WaitAsync();

            try
            {
                if (_cache.TryGetValue(cacheKey, out MediaMetadata cached))
                {
                    return Ok(new { cached.Url, cached.ProcessedAt, Source = "cache" });
                }

                var result = await ProcessAndCacheAsync(file, sanitizedDeviceId, contentHash, cacheKey);
                return Ok(new { result.Url, result.ProcessedAt, Source = "processed" });
            }
            finally
            {
                semaphore.Release();
            }
        }

        [HttpGet("media/{deviceId}/{hash}")]
        public IActionResult GetMedia(string deviceId, string hash)
        {
            var sanitizedDeviceId = SanitizeDeviceId(deviceId);
            var cacheKey = BuildCacheKey(sanitizedDeviceId, hash);

            if (_cache.TryGetValue(cacheKey, out MediaMetadata cached))
            {
                return Ok(cached);
            }
            return NotFound();
        }

        private async Task<MediaMetadata> ProcessAndCacheAsync(
            IFormFile file, string deviceId, string contentHash, string cacheKey)
        {
            var metadata = await _processor.ProcessMediaAsync(file, deviceId);
            metadata.ContentHash = contentHash;
            metadata.DeviceId = deviceId;

            var cacheOptions = new MemoryCacheEntryOptions()
                .SetSlidingExpiration(TimeSpan.FromMinutes(30))
                .SetAbsoluteExpiration(TimeSpan.FromHours(4))
                .SetSize(1);

            _cache.Set(cacheKey, metadata, cacheOptions);
            return metadata;
        }

        private string BuildCacheKey(string deviceId, string contentHash)
        {
            // Normalize the cache key to prevent duplicates
            var rawKey = $"media:{deviceId}:{contentHash}";
            return NormalizeCacheKey(rawKey);
        }

        private string NormalizeCacheKey(string key)
        {
            // Collapse any repeated colons and trim
            var normalized = key.Replace("::", ":").Trim();
            // Truncate to prevent memory issues with long keys
            if (normalized.Length > 128)
                normalized = normalized.Substring(0, 128);
            return normalized.ToLowerInvariant();
        }

        private string SanitizeDeviceId(string deviceId)
        {
            // Remove path separators and null bytes
            var sanitized = deviceId
                .Replace("/", "")
                .Replace("\\", "")
                .Replace("\0", "");
            // Allow alphanumeric, hyphens, and colons (for MAC addresses)
            var sb = new StringBuilder();
            foreach (var c in sanitized)
            {
                if (char.IsLetterOrDigit(c) || c == '-' || c == ':')
                    sb.Append(c);
            }
            return sb.ToString();
        }

        private async Task<string> ComputeContentHashAsync(IFormFile file)
        {
            using var sha = SHA256.Create();
            using var stream = file.OpenReadStream();
            var hashBytes = await Task.Run(() => sha.ComputeHash(stream));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }

    public class MediaMetadata
    {
        public string Url { get; set; }
        public string ContentHash { get; set; }
        public string DeviceId { get; set; }
        public DateTime ProcessedAt { get; set; }
        public string MimeType { get; set; }
        public long FileSize { get; set; }
    }

    public interface IMediaProcessor
    {
        Task<MediaMetadata> ProcessMediaAsync(IFormFile file, string deviceId);
    }
}
